from datetime import datetime, timedelta
access_token='eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJzdWIiOiJzaW1wbGVfbm90ZSthbmdlbGljYS53aWxzQGdtYWlsLmNvbSIsImV4cCI6MTY4NDQxMjA5OH0.6ySJXKnhKUO9K2PbEd9u1h9v7lsCC75Oztrh7oP3njI'

# refetch and compute streaks
all_notes=[]
page_index=0
page_limit=20
while True:
    resp=apis.simple_note.search_notes(access_token=access_token, query='', tags=['habit-tracker'], page_index=page_index, page_limit=page_limit)
    if not isinstance(resp,list) or len(resp)==0:
        break
    all_notes.extend(resp)
    page_index+=1

items=[]
for n in all_notes:
    title=n.get('title','')
    if '--' not in title: 
        continue
    date_str=title.split('--',1)[1].strip()
    try:
        d=datetime.strptime(date_str,'%Y-%m-%d').date()
    except Exception:
        continue
    items.append((n.get('note_id'), d, title))

ate_by_date={}
for note_id, d, title in items:
    note=apis.simple_note.show_note(note_id=note_id, access_token=access_token)
    content=note.get('content','')
    ate_val=None
    for line in content.splitlines():
        line=line.strip()
        if line.startswith('ate_homemade_meals:'):
            ate_val=line.split(':',1)[1].strip().lower()
            break
    ate_by_date[d]=(ate_val=='yes')

dates_sorted=sorted(ate_by_date.keys())

streaks=[]
cur_start=None
cur_len=0
prev=None
for dd in dates_sorted:
    if ate_by_date[dd]:
        if cur_len==0:
            cur_start=dd
            cur_len=1
        else:
            if prev is not None and (dd-prev).days==1:
                cur_len+=1
            else:
                streaks.append((cur_start, prev, cur_len))
                cur_start=dd
                cur_len=1
    else:
        if cur_len>0:
            streaks.append((cur_start, prev, cur_len))
        cur_len=0
        cur_start=None
    prev=dd
if cur_len>0:
    streaks.append((cur_start, prev, cur_len))

streaks_sorted=sorted(streaks, key=lambda x:x[2], reverse=True)
print('all_streaks (start,end,len):', [(s.isoformat(), e.isoformat(), l) for s,e,l in streaks_sorted])
print('max_len:', streaks_sorted[0][2] if streaks_sorted else 0)
